const D = x => (x instanceof Decimal ? x : new Decimal(x));
const LIMIT = D('1.79e308');

// ---------- number formatting ----------
const SUF = ['', 'K', 'M', 'B', 'T', 'Qa', 'Qi', 'Sx', 'Sp', 'Oc', 'No', 'Dc', 'UDc', 'DDc', 'TDc', 'QaDc', 'QiDc', 'SxDc', 'SpDc', 'OcDc', 'NoDc', 'Vg', 'UVg', 'DVg', 'TVg', 'QaVg', 'QiVg', 'SxVg', 'SpVg', 'OcVg', 'NoVg', 'Tg'];
function fmt(x, dp = 2) {
  x = D(x);
  if (x.lt(0)) return '-' + fmt(x.neg(), dp);
  if (x.lt(1000)) { const n = x.toNumber(); return n < 10 && dp ? n.toFixed(n % 1 ? 2 : 0) : n < 100 && dp ? n.toFixed(n % 1 ? 1 : 0) : Math.floor(n).toString(); }
  const e = x.exponent, not = (S && S.set.not) || 'suffix';
  if (e >= 1e6) return 'e' + fmt(D(e), 2);
  if (not === 'suffix' && e < SUF.length * 3) { const k = Math.floor(e / 3); return (x.mantissa * 10 ** (e - k * 3)).toFixed(2) + SUF[k]; }
  if (not === 'eng') { const k = Math.floor(e / 3) * 3; return (x.mantissa * 10 ** (e - k)).toFixed(2) + 'e' + k; }
  return x.mantissa.toFixed(2) + 'e' + e.toLocaleString('en-US');
}
function fmtT(s) {
  s = Math.max(0, Math.floor(s));
  const d = Math.floor(s / 86400), h = Math.floor(s / 3600) % 24, m = Math.floor(s / 60) % 60, x = s % 60;
  return d ? `${d}d ${h}h` : h ? `${h}h ${m}m` : m ? `${m}m ${x}s` : `${x}s`;
}


