const BADGES = [
  ['tap', 'Tapper', 'hand', 'taps', () => S.st.taps, [100, 1e3, 1e4, 1e5, 1e6]],
  ['crit', 'Lucky Strike', 'sparkle', 'critical taps', () => S.st.crits, [25, 250, 2500, 25000, 250000]],
  ['build', 'Builder', 'gear', 'generators in one run', () => S.gens.reduce((a, b) => a + b, 0), [50, 200, 500, 1000, 2500]],
  ['upg', 'Tinkerer', 'flask', 'upgrades bought', () => S.st.upg, [10, 50, 150, 400, 1000]],
  ['hoard', 'Hoarder', 'bolt', 'digits of lifetime energy', () => Math.max(0, S.lifeE.log10()), [6, 15, 30, 80, 200]],
  ['reb', 'Reborn', 'diamond', 'Rebirths', () => S.cnt.reb, [1, 10, 50, 200, 1000]],
  ['sing', 'Collapser', 'hole', 'Singularities', () => S.cnt.sing, [1, 5, 25, 100, 500]],
  ['asc', 'Ascendant', 'arrowup', 'Ascensions', () => S.cnt.asc, [1, 5, 20, 75, 300]],
  ['tra', 'Transcendent', 'spiral', 'Transcendences', () => S.cnt.tra, [1, 3, 10, 40, 150]],
  ['inf', 'Infinite', 'inf', 'Infinities', () => S.cnt.inf, [1, 3, 10, 30, 100]],
  ['kill', 'Slayer', 'sword', 'bosses defeated', () => S.st.kills, [1, 10, 40, 120, 400]],
  ['art', 'Collector', 'gem', 'artifacts found', () => Object.keys(S.arts).length, [1, 5, 10, 18, 25]],
  ['ach', 'Achiever', 'trophy', 'achievements', () => Object.keys(S.ach).length, [10, 40, 80, 130, 175]],
  ['ev', 'Storm Chaser', 'comet', 'events caught', () => S.st.ev, [5, 25, 100, 400, 1500]],
  ['chal', 'Challenger', 'swords', 'challenge clears', () => S.st.chal, [1, 3, 6, 10, 20]],
  ['pet', 'Tamer', 'heart', 'eggs hatched', () => S.pets.hatched, [1, 3, 6, 12, 25]],
  ['story', 'Storyteller', 'scroll', 'chapters finished', () => S.story.claimed, [1, 5, 12, 24, 38]],
  ['vet', 'Veteran', 'hourglass', 'days since you started', () => (Date.now() - S.started) / 864e5, [1, 3, 7, 30, 100]],
  // added in 0.9: 12 more tracks
  ['eps', 'Powerhouse', 'sun', 'digits of your best energy per second', () => Math.max(0, S.st.maxEps.log10()), [5, 15, 40, 100, 250]],
  ['abil', 'Spellslinger', 'cycle', 'abilities used', () => S.st.ab, [5, 50, 250, 1000, 5000]],
  ['res', 'Researcher', 'lens', 'research projects done', () => Object.keys(S.res).length, [1, 5, 12, 22, 32]],
  ['perk', 'Perk Hoarder', 'shard', 'Fragment perk levels', () => Object.values(S.perks).reduce((a, b) => a + (+b || 0), 0), [3, 15, 40, 80, 150]],
  ['dim', 'Explorer', 'planet', 'dimensions unlocked', () => DIMS.filter(d => S.dims[d.id] && S.dims[d.id].u).length, [1, 2, 4, 6, 8]],
  ['hole', 'Gravity Well', 'hole', 'digits of Black Hole mass', () => Math.max(0, S.bh.log10()), [3, 10, 25, 50, 100]],
  ['tier', 'Tier Climber', 'arrows', 'highest generator tier owned', () => S.gens.reduce((m, g, i) => (g > 0 ? i + 1 : m), 0), [3, 5, 7, 9, 10]],
  ['hunt', 'Big Game', 'crown', 'strongest boss defeated', () => BOSSES.reduce((m, b) => (S.boss.k[b.i] ? b.i + 1 : m), 0), [2, 5, 10, 15, 20]],
  ['love', 'Pet Pal', 'heart', 'total pet levels', () => Object.values(S.pets.own).reduce((a, o) => a + o.lvl, 0), [5, 20, 50, 120, 240]],
  ['evo', 'Evolver', 'sparkle', 'pet evolutions', () => Object.values(S.pets.own).reduce((a, o) => a + (o.lvl >= 10) + (o.lvl >= 20), 0), [1, 3, 6, 10, 16]],
  ['time', 'Dedicated', 'moonz', 'hours played', () => S.st.play / 3600, [1, 5, 24, 100, 500]],
  ['ult', 'Ultra', 'crown', 'Ultra Prestiges', () => S.cnt.ult || 0, [1, 3, 10, 25, 60]],
  ['upts', 'Point Collector', 'gem', 'Ultra Points earned', () => (S.upTotal ? S.upTotal.toNumber() : 0), [5, 50, 500, 2500, 10000]],
  ['secret', 'Secret Keeper', 'question', 'secrets found', () => Object.keys(S.sec).length, [1, 2, 4, 6, 9]],
].map(([id, n, spr, what, val, th]) => ({ id, n, spr, what, val, th }));

