// ---- 0.10.1 story pass: middle scenes, longer openings and endings, and week-long pacing for the main story ----
const STORY_MID = {"Night Shift": [["vela", "Four in the morning. The Engine makes a noise when I yawn. Like it's yawning back."], ["vela", "I tried singing to it. Production went up two percent. I'm not saying that's related."], ["vela", "I'm also not saying it isn't."]], "Kiro's List": [["kiro", "Item four, which I am adding now: eat something."], ["vela", "That's not an engine task."], ["kiro", "A builder who faints is not a builder. Item four stays."]], "Second Climb": [["vela", "Third reset. I didn't even flinch. I just pressed it and went to make tea."], ["kiro", "Builder nine also made tea. Builder nine forgot the tea for six climbs."], ["vela", "I'll set a timer."]], "Storm Season": [["vela", "Three storms in an hour. The dome smells like lightning and cinnamon."], ["kiro", "Cinnamon is new. I am writing that down."], ["kiro", "The Golem is close. I can feel it in the floor. Please stop dancing."]], "Many Heads": [["vela", "Two heads down. The third one is sulking behind the quasar."], ["kiro", "Hydras do not sulk. They regroup."], ["vela", "It's sulking, Kiro. Look at its face."]], "Feeding the Dark": [["vela", "I fed it a whole afternoon of energy. It burped. A black hole burped."], ["arch", "That is a good sign. Hungry holes are silent."], ["arch", "The Leviathan is circling. It can smell a happy black hole from very far away."]], "One Hand Tied": [["vela", "No taps. My thumb keeps twitching toward the reactor on its own."], ["arch", "Good. Notice the twitch. Then do not tap."], ["kiro", "I have taped her thumb to a pencil. For science."]], "Molten Light": [["vela", "The Titan's clocks are all running at different speeds. One of them is running backwards."], ["kiro", "Do not stand near the backwards one. You will get younger and then you will be annoying."], ["vela", "I was already annoying."]], "Old Builders": [["vela", "Another relic. Same initials. S. A. B. She was everywhere."], ["arch", "She went further than anyone. She left things behind on purpose."], ["vela", "Like breadcrumbs. For someone to follow."]], "Rules Are Suggestions": [["nyx", "You wrote a law that makes Mondays shorter. Reality did not like that one."], ["vela", "It was a test!"], ["nyx", "Everything is a test. Some of them you pass by accident."]], "The Other Builder": [["sable", "So you're the one with the tidy engine. I can hear it purr from here."], ["vela", "Is that... good?"], ["sable", "Mine screamed. Purring is better. Keep waking the worlds."]], "Teeth in the Dark": [["vela", "The Devourer ate half a nebula on its way here. It left the other half like a crust."], ["sable", "It always leaves the crust. Picky eater."], ["kiro", "I have a theory about the crust. Nobody has asked for my theory."]], "The Reaper's Due": [["nyx", "The Reaper asked its question. You did not answer yet."], ["vela", "What was the question?"], ["nyx", "Who do you trust. Take your time. It will wait. It is very good at waiting."]], "Edge of Counting": [["vela", "Two hundred and eighty-one digits. The Engine paused for a whole second before it wrote the next one."], ["sable", "It's scared. Mine was too. Talk to it."], ["vela", "...It's okay. You can keep counting. I've got you."]], "The Last Singularity": [["vela", "It opened one eye. Just one. The whole dome went quiet."], ["arch", "That is how it begins. I have seen it begin many times. I have seen it end once."], ["sable", "Twice. Count properly."]], "After the Wall": [["vela", "Infinity Points don't decay, don't reset, don't care. They just sit there being enormous."], ["kiro", "I have named one of them. It is called Gerald."], ["vela", "You can't name a point, Kiro."]], "The Aeon Wyrm": [["vela", "The Wyrm bit off an hour. I lost an hour. Where did the hour go?"], ["sable", "Inside the Wyrm. You'll get it back when it dies. Probably."], ["kiro", "I would also like my hour back. I had plans for it."]], "The Hollow Choir": [["vela", "They're singing my name now. Not Vela. My whole name. Nobody uses my whole name."], ["sable", "They do that. They try to sound like home. Don't answer."], ["nyx", "I am humming over them. You are welcome."]], "Sable's Bargain": [["vela", "If I break the Colossus, Sable gets a clear line. If I don't, Nyx stays calm."], ["arch", "And either way, I write it down."], ["kiro", "For the record, I am on the side of whoever has snacks."]], "Faster Hands": [["vela", "First Singularity of the new climb in four minutes. Four. It took me two days the first time."], ["sable", "Told you. The good stuff compounds."], ["kiro", "I am timing everything. You are setting records against yourself."]], "The Shade": [["vela", "The Shade hits like Nyx talks. Slow and from everywhere."], ["nyx", "I would like to apologise for my shade. I would also like you to keep hitting it."], ["sable", "That's the nicest thing Nyx has ever said."]], "The Record Eater": [["arch", "It has eaten the entire letter K. Every builder whose name started with K is gone."], ["kiro", "I have checked. I am still here. I am very relieved."], ["arch", "You are filed under D. For drone."]], "Sable's Engine": [["sable", "I can hear it. My old engine. It's humming the same song I used to hum while I worked."], ["vela", "We'll stop it. Gently, if we can."], ["sable", "There's no gently with that thing. But thanks."]], "Entropy's Daughter": [["vela", "The Queen sent a letter. On paper. It says please."], ["nyx", "She is polite before she is terrible. It is a family trait."], ["sable", "Wait, you two are related?"]], "The Unmaker": [["vela", "It took a bolt out of the Omega Engine. One bolt. I felt it in my teeth."], ["kiro", "I have replaced the bolt with a better bolt. I will not say where I found it."], ["sable", "Kiro, that's from my old engine. ...Keep it."]], "The First Engine": [["arch", "It is reading the record. All of it. Every builder. Every page."], ["vela", "Is it reading mine?"], ["arch", "It stopped on yours. It has been on your page for a while now."]], "The Spark": [["vela", "Update. There are slots around the core. When I fit a cell into one, it makes energy on its own. Without me touching it."], ["vela", "I put in a second cell. Then a third. It's... humming louder. Happier? Machines don't get happy."], ["vela", "Note to self: stop saying the machine is happy."]], "Chain Reaction": [["kiro", "Observation: you tap with your thumb. Builder seven tapped with a spoon. Builder seven did not last."], ["vela", "Why are you telling me this?"], ["kiro", "Encouragement. Also: watch the sky. Storms of energy pass through here. Catch one and the Engine drinks deep."]], "Critical Mass": [["vela", "I did it. I pressed the button. Everything went dark for one second and I screamed a little."], ["kiro", "I recorded the scream. For the archive."], ["vela", "Delete that."], ["kiro", "Fragments can buy perks. Choose carefully. Or don't. You can always earn more."]], "Echoes in the Wire": [["vela", "The Wraith is gone. It made a sound like a kettle when it broke apart."], ["kiro", "Monsters drop artifacts. Keep them. They are pieces of engines that lost."], ["vela", "That's a cheerful thought. The egg is warm, by the way. And wobbling."]], "Gravity": [["arch", "Your Black Hole is young. It eats slowly. Be patient with it."], ["vela", "It's beautiful. It's terrifying. It's both. Is that allowed?"], ["arch", "It is the only correct reaction. I have written it down."]], "The Ladder": [["vela", "I finished a trial. My hands are shaking. Is that normal?"], ["kiro", "Builder twelve's hands also shook. Then he got annoying."], ["vela", "I will try very hard not to get annoying."]], "Worlds Beyond": [["vela", "I collected another artifact. A cracked lens. When I look through it the numbers look bigger."], ["arch", "They are bigger. Artifacts bend the Engine in small ways. Collect them and the small ways add up."], ["kiro", "Builder four had a full collection. Builder four also had a museum. Nobody visited the museum."]], "The Void Answers": [["vela", "I wrote my first Law. Reality just... agreed with me."], ["nyx", "Reality agrees with whoever writes clearly. Write two. See how they argue with each other."], ["kiro", "I would like to be on the record as nervous."]], "What Nyx Wants": [["vela", "The bosses are getting bigger. The last one had a clock for a face."], ["arch", "The Chrono Serpent. It ate three builders' afternoons before you. I am glad to cross it out."], ["nyx", "Keep going. They guard the wall because they are afraid of what is past it."]], "Infinity": [["vela", "I hit the wall. Everything went white. When it came back, I had one Infinity Point and my hands were glowing."], ["arch", "That is normal. The glowing fades. The point does not."], ["nyx", "Now the handle. Break it, Vela."]], "Past the Wall": [["vela", "I've been earning Infinity Points for days. The Ultra button keeps getting brighter."], ["kiro", "It is waiting for you. I am also waiting for you. Both of us are very patient."], ["nyx", "Kiro is not patient. Kiro checks the button every eleven seconds."]], "The Omega Engine": [["vela", "Five Ultra climbs. Each one faster. I can do a whole night's work before my tea gets cold."], ["nyx", "And you still tap the core on day one of every climb. Even though you don't need to."], ["vela", "It's tradition. And it likes it."]]};
const STORY_FULL = {"The Spark": {"intro": [["vela", "Okay. Okay okay okay. It's humming."], ["vela", "Day one, log entry. There's a room under the observatory that isn't on any blueprint. In it, a machine. Older than the building. Older than the hill, probably."], ["vela", "It has a core. When I tap the core, it gives me energy. A tiny bit. Every single time."], ["vela", "That's not how physics works. Energy doesn't come from nowhere. I have a degree that says so, framed, on a wall."], ["vela", "There's writing on the casing. Most of it I can't read. One word repeats everywhere: ENGINE."], ["vela", "Fine. Rules for myself. One: don't panic. Two: write everything down. Three: keep tapping, carefully, for science."], ["vela", "If anyone finds this log, I was very calm the whole time."]], "outro": [["vela", "Ten cells, all stable. The hum has a rhythm now, like breathing."], ["vela", "And there's a panel on the side that wasn't there yesterday. I'm sure it wasn't."], ["vela", "Something inside it is knocking. Politely."]]}, "Chain Reaction": {"intro": [["kiro", "Unfolding. Unfolding. Ow. Done. Hello."], ["vela", "AAAH. A drone. There was a drone in my wall."], ["kiro", "Correction: the wall was around me. I was here first. Designation K1-RO. You may call me Kiro. Everyone who climbed before you did."], ["vela", "Everyone who... how many people have found this thing?"], ["kiro", "Several. Not many. Most of them stopped at the first hundred cells. I have opinions about that."], ["kiro", "The Engine grows in tiers. Cells feed cores. Cores feed reactors. Every tier makes the one below it matter more. It is a chain."], ["vela", "And if I keep building the chain?"], ["kiro", "Then the numbers stop being numbers you can say out loud. That is when it gets interesting."]], "outro": [["kiro", "A Plasma Reactor. Good. The chain holds three links now."], ["vela", "My hands smell like ozone and I have not slept. I've never felt better."], ["kiro", "That is normal for builders. The not sleeping part is not normal. Sleep, Vela."]]}, "Critical Mass": {"intro": [["vela", "It's slowing down. Every cell costs more than the last, and the numbers crawl."], ["kiro", "You have hit the ceiling of a single climb. Every builder does. Now comes the part they hated."], ["vela", "Please don't say what I think you're going to say."], ["kiro", "Rebirth. You collapse everything you built into Fragments. The cells, the cores, all of it. Gone."], ["vela", "That's insane. I spent all night on those."], ["kiro", "And you will spend twenty minutes building them back, faster, because each Fragment makes everything stronger. Forever."], ["vela", "...How much faster?"], ["kiro", "Enough that you will laugh at your first night. Kindly. You will laugh kindly."]], "outro": [["vela", "Back to where I was in a quarter of the time. You were right. I laughed."], ["kiro", "Kindly?"], ["vela", "Mostly kindly. What's that noise? Something in the walls is singing."]]}, "Echoes in the Wire": {"intro": [["kiro", "The singing is the Engine remembering. Every builder left traces in the wiring. Research reads them."], ["vela", "So I can learn from the people before me?"], ["kiro", "You can learn what they discovered. Not what they regretted. That part did not get written down."], ["vela", "Kiro. Something just looked at me through the window. Something made of fog."], ["kiro", "A Nebula Wraith. They feed on young engines. You will have to fight it."], ["vela", "Fight it with what? I'm an engineer. My combat experience is losing arguments with printers."], ["kiro", "You tap. Hard. The Engine does the rest."], ["vela", "Also, unrelated: there is an egg on my desk. I did not put an egg on my desk."]], "outro": [["vela", "It hatched. It's... small and glowing and it sat on my shoe."], ["kiro", "Companions are rare. It chose you. Feed it energy and it will grow."], ["vela", "I'm a parent now. I'm a parent to a glowing thing. Log entry ends."]]}, "Gravity": {"intro": [["vela", "Kiro, the floor is bending. Not cracking. Bending. Towards the core."], ["kiro", "You have made so much energy that it is starting to weigh something. This is a Singularity. It has been a long time."], ["arch", "Indeed it has."], ["vela", "WHO SAID THAT."], ["arch", "Forgive me. I am the Archivist. I keep the record of every engine that ever climbed. Yours just wrote itself onto a new page."], ["arch", "Collapse your Fragments into a Singularity and a Black Hole will open beside the core. Feed it, and it pulls the whole Engine forward."], ["vela", "You want me to feed a black hole. In my basement."], ["arch", "I want nothing. I only write down what builders do. But the ones who fed it went further."]], "outro": [["arch", "A Black Hole of real weight. Good. The record now calls you a builder of the second rung."], ["vela", "How many rungs are there?"], ["arch", "That depends on how high you are willing to climb. Rest now. I will be here."]]}, "The Ladder": {"intro": [["arch", "Builders before you tested themselves. They called these the Trials. Rules that make the climb harder, on purpose."], ["vela", "Why would anyone make it harder on purpose?"], ["arch", "Because the Engine pays for proof. Finish a trial and it remembers that you can."], ["kiro", "Builder twelve finished every trial in one week. Builder twelve was very annoying about it."], ["arch", "And beyond the trials, Ascension. You give up your Singularities as well as your Fragments, and gain Cores of light."], ["vela", "Give up everything twice. Great. Love that. Totally fine."], ["arch", "You said that before your first Rebirth. Read your own log, Vela."]], "outro": [["arch", "You Ascended. The Engine is lighter now. It has learned to climb."], ["vela", "It's so fast. Everything I built in a day comes back in minutes."], ["arch", "Yes. And the faster you climb, the more you will see. Look out of the window, Vela. Not the basement window. The other one."]]}, "Worlds Beyond": {"intro": [["vela", "There's a second sky. Behind the first one. I can see it if I look sideways."], ["arch", "Dimensions. Each one runs on a different kind of energy. Matter, plasma, things without names yet."], ["kiro", "Each one also has rules. Plasma cools if you leave it. Quantum flickers. Some get stronger the longer you ignore them."], ["vela", "So it's not one engine anymore. It's a whole... ecosystem."], ["arch", "It was always an ecosystem. You just could not see the rest of it."], ["vela", "And the monsters? Are there more of them out there?"], ["kiro", "Yes. Bigger. Some of them have names in the record. Some of them have teeth in the record."], ["vela", "Good. Great. I'll bring snacks."]], "outro": [["vela", "Three worlds open. Five artifacts. The basement is glowing in colors I don't have names for."], ["arch", "You are past where most builders stopped. The record grows quiet beyond this point."], ["arch", "Except for one voice. It has been waiting for you, I think."]]}, "The Void Answers": {"intro": [["nyx", "You are loud, little builder."], ["vela", "Kiro, did you hear that?"], ["kiro", "I did not. I would like to state that I did not, for the record."], ["nyx", "I am what is left between the worlds. The space your engines push aside. I am Nyx."], ["nyx", "Every builder climbs. Every builder pushes. I get smaller. I have been patient."], ["vela", "I didn't know. I'm sorry. I didn't know anything was there."], ["nyx", "Nobody knows. That is what I am. But you said sorry. No builder has said sorry before."], ["nyx", "Transcend, Vela. Burn your Cores into the Void and I will give you Essence. And Laws. Rules you can write onto reality itself."]], "outro": [["nyx", "You Transcended. The Void is a little bigger now. I can breathe."], ["vela", "Wait. Transcending gives you space back?"], ["nyx", "Yes. You are the first builder who climbed in a way that left room for me. I did not expect that."], ["nyx", "Raise your companion. Fight what comes. Then come and find me. I want to show you something."]]}, "What Nyx Wants": {"intro": [["nyx", "Look up, Vela. Past the dimensions. Past the record."], ["vela", "It's... a wall. A wall made of numbers. They just stop."], ["arch", "Infinity. 1.79 times ten to the three hundred and eight. The largest number the old engines could hold."], ["nyx", "Almost every builder who reached it stopped there. The Engine filled up. They called it the end."], ["nyx", "It is not the end. It is a door with no handle. I want you to make a handle."], ["vela", "Why me?"], ["nyx", "Because you said sorry. Because you feed your little glowing thing even when it does nothing useful. Because you write everything down."], ["kiro", "She does write everything down. It is very long. I have read all of it."], ["nyx", "Defeat the guardians. Grow your companion. Then reach Infinity, and we will see what is behind it."]], "outro": [["vela", "Six guardians down. My companion is huge now. It sleeps on the reactor and the reactor purrs."], ["nyx", "You are ready. Or as ready as anyone has been."], ["kiro", "For the record: I believe in you. Please do not tell anyone I said something so unprofessional."]]}, "Infinity": {"intro": [["arch", "Here it is. The page I have never been able to write."], ["vela", "Okay. Okay okay okay. Just like day one."], ["kiro", "Your energy output is very large. I have stopped being able to say it out loud. As promised."], ["nyx", "When you reach the wall, everything collapses into a single point. Infinity Points. They survive everything."], ["arch", "And then there is the matter of breaking it. The record has a blank space here, waiting."], ["vela", "What happens if I break Infinity?"], ["nyx", "Then numbers keep going. Then the climb has no ceiling. Then you will need a new word for 'big'."], ["vela", "I'll make one up. I'm good at that. Ask Kiro."]], "outro": [["vela", "It broke. Not like glass. Like a door opening."], ["arch", "I am writing your name on a new page. Past the wall."], ["nyx", "Thank you. There is room on the other side. For me, too."], ["kiro", "Log entry, written by Kiro since Vela is crying: she did it. Day one was a while ago. She was not calm the whole time."], ["vela", "Kiro!"], ["kiro", "The record must be accurate."]]}, "The Omega Engine": {"intro": [["arch", "The last page of the record holds a blueprint. The Omega Engine. No builder has finished it."], ["nyx", "Because it does not make energy. It makes the climb itself. Whoever builds it never needs to climb again."], ["vela", "So it's the end?"], ["nyx", "It is the end of having to. What you do after is yours."], ["kiro", "It will take a very long time. I have cleared my schedule. I have no schedule. I have never had a schedule."], ["arch", "Builders measure this part in seasons, not days. Take your time. The record is patient."]], "outro": [["vela", "It's done. It's actually done."], ["arch", "I am writing your name at the top of the record. Underneath it I am writing: she did not panic."], ["vela", "I panicked a lot."], ["arch", "I know. I left that part out."], ["nyx", "Stay a while. The view is good from here."]]}};
const STORY_PACE = [[10, 20, 30, 45, 60, 90, 120, 150, 180, 210, 240, 270, 300, 330, 390, 450, 480, 510, 540, 600, 660, 720, 780, 840], [1, 1, 1, 1, 1, 1, 2, 2, 2, 3, 3, 3, 4, 4, 4, 5, 5, 5, 6, 6, 6, 7, 7, 7]];
CHAPTERS.forEach((c, i) => {
  if (STORY_MID[c.n]) c.mid = STORY_MID[c.n];
  if (STORY_FULL[c.n]) Object.assign(c, STORY_FULL[c.n]);
  if (i < STORY_PACE[0].length) {
    const m = STORY_PACE[0][i], d = STORY_PACE[1][i];
    c.m.push([m < 120 ? `Spend ${m} minutes with the Engine` : `Spend ${m % 60 ? (m / 60).toFixed(1) : m / 60} hours with the Engine`, () => [S.st.act / 60, m]]);
    if (d > 1) c.m.push([`Play on ${d} different days`, () => [S.st.dayN, d]]);
  }
});
// ---- 0.13: three new characters, woven into the story ----
Object.assign(CHARS, {
  juno: { n: 'Juno Pell', role: 'Courier pilot who flies through energy storms' },
  bram: { n: 'Bram Holloway', role: 'Stardust miner, forty years in the same star' },
  echo: { n: 'Echo', role: 'What is left of a lost builder, living in the record' },
});
const STORY_EXTRA = {
  'Storm Season': { mid: [['juno', 'Coming in hot! Sorry! Is this the observatory with the weird glowing machine?'], ['vela', '...Who are you? How did you land on the dome?'], ['juno', "Juno Pell, courier. I fly parts through storms nobody else will fly through. Somebody ordered a Fusion Plant coil to this address."], ['kiro', 'I ordered it. Item twelve.'], ['juno', "Sign here. And whatever you're building, it's making the storms worse. Or better. Depends if you like storms. I like storms."]] },
  'Feeding the Dark': { mid: [['juno', "I flew past your black hole on the way in. It waved at me. I'm choosing not to think about that."], ['vela', "Black holes don't wave, Juno."], ['juno', 'This one does. Tell it I said hi.']] },
  'Molten Light': { mid: [['bram', 'Oi! You there, with the drone. You are standing on my seam.'], ['vela', 'Your what?'], ['bram', "Bram Holloway. I've been mining stardust out of this star for forty years. Long before your engine put a door in it."], ['bram', "Stardust doesn't like being rushed. Grow it slow and it grows you back. That's free advice. The next bit costs a sandwich."], ['kiro', 'I will add sandwiches to the list.']] },
  'Old Builders': { mid: [['echo', '...hello? Is someone reading the record? I can feel the pages turning.'], ['arch', 'Echo. I wondered when you would wake.'], ['echo', "I'm what's left of builder nine. The one who made tea. I'm mostly tea now, honestly."], ['vela', "You're a ghost?"], ['echo', "I'm a footnote with feelings. Keep collecting the relics. Each one wakes a little more of me."]] },
  'Edge of Counting': { mid: [['bram', 'Two hundred and eighty digits. When I started mining we counted in buckets.'], ['juno', "I can't fly faster than the numbers any more. They keep lapping me."], ['echo', 'Builder nine never got this far. I am very excited. Please do not tell the Archivist.']] },
  'After the Wall': { mid: [['echo', 'Past the wall I can remember more. There was a song we sang while we built. The first line goes: hmmmm.'], ['kiro', 'That is not a line.'], ['echo', 'It was a very good hmmmm.']] },
  "Sable's Engine": { mid: [['juno', "I'll fly a line to it. Nobody gets left in the dark on my route."], ['bram', 'And I will dig you a way in. Old engines have old foundations, and old foundations have cracks.'], ['sable', 'You two would have liked my crew. Thank you.']] },
  'The First Engine': { outroBefore: [['echo', 'I remember everything now. Every builder, every page. Thank you for reading us, Vela.'], ['juno', 'Delivery complete. Best route I ever flew.'], ['bram', 'Not bad for a kid with a drone.']] },
};
CHAPTERS.forEach(c => {
  const x = STORY_EXTRA[c.n]; if (!x) return;
  if (x.mid) c.mid = [...(c.mid || []), ...x.mid];
  if (x.outroBefore) c.outro = [...c.outro.slice(0, -1), ...x.outroBefore, ...c.outro.slice(-1)];
});

// ---- 0.16: four chapters and four characters for the worlds past the multiverse, placed right after the first chapter past Infinity ----
Object.assign(CHARS, {
  facet: { n: 'Facet', role: 'A crystal made of smaller copies of itself' },
  alev: { n: 'Alev', role: "Vela's reflection from the Mirror world" },
  morrow: { n: 'Morrow', role: 'Sleepy giant who dreams whole universes' },
  lumen: { n: 'Lumen', role: 'The first light, older than every engine' },
});
const dimM = (id, label) => [[`Unlock the ${label} dimension`, () => [S.dims[id].u, 1]], [`Grow ${label}'s ${DIMS.find(d => d.id === id).res} to 1e12`, () => [S.dims[id].u ? Math.min(12, Math.floor(oom(S.dims[id].r))) : 0, 12]]];
const CH16 = [
  { n: 'Smaller Copies', who: 'facet', syn: 'Past the multiverse, everything repeats itself, a little smaller each time. Something in there is talking.',
    intro: [['arch', 'The record should stop here. The multiverse was the last page.'], ['vela', 'Then why is the Engine still pulling? Kiro, read me the needle.'], ['kiro', 'The needle points past the edge of the page. I do not have a word for that direction.'], ['facet', 'Hello. (Hello.) ((Hello.))'], ['vela', 'Did that echo just get smaller?'], ['facet', 'I am Facet. I am made of me. Every piece of me is a smaller me, all the way down. Please mind your step.']],
    mid: [['facet', 'You opened my world. Every Shard you grow grows a smaller copy of itself. (Of itself.)'], ['kiro', 'I tried to count the copies. I have stopped trying to count the copies.'], ['facet', 'Smart drone. Count the pattern, not the pieces.']],
    outro: [['facet', 'You held the pattern steady. Most builders stare at one triangle and fall in.'], ['vela', "I'm still a little dizzy, honestly."], ['facet', 'Look past me. That shine is the next world. Something in it looks exactly like you. (Like you.)']],
    m: dimM('fractal', 'Fractal') },
  { n: 'Through the Glass', who: 'alev', syn: 'A perfectly still lake reflects everything, Vela included. Her reflection has opinions.',
    intro: [['vela', "It's a lake. A flat, silver lake, out here. And that's me in it."], ['alev', "Hi. You're standing on my ceiling."], ['vela', 'Kiro. My reflection is talking.'], ['kiro', 'Your reflection is also tapping her reactor twice as fast as you.'], ['alev', "I'm Alev. Vela, backwards. I got everything you didn't. I sleep eight hours. I drink my coffee while it's hot."], ['alev', 'And I never stop tapping. Out here, the world only listens to busy hands.']],
    mid: [['alev', 'See? Tap and the lake shines. Stop and it goes dull.'], ['vela', 'So this world wants the exact opposite of the Void.'], ['alev', 'Everything here is the opposite of somewhere. Even me. Especially me.'], ['juno', "Okay, which one of you signs for the package? I'm not flying back for the other one."]],
    outro: [['alev', "You kept up. I was sure you'd give up and go to bed. That's the one thing I never do."], ['vela', 'Will I see you again?'], ['alev', 'Every time you look at a window. Go on. Someone past the lake is having a very long nap.']],
    m: dimM('mirror', 'Mirror') },
  { n: 'Lullaby Engine', who: 'morrow', syn: 'A sleepy giant in a nightcap has been dreaming whole universes. Maybe yours too.',
    intro: [['bram', 'Forty years down the mines and I never saw clouds in space. Pink ones. With a moon.'], ['morrow', "Mm. Shh. You're in my dream. Please wipe your boots."], ['vela', 'Your dream? Whose dream is this?'], ['morrow', 'Mine. Morrow. I dream the worlds and they keep going. If I wake up, some of them stop.'], ['kiro', 'I would like to formally request that nobody wakes him up.'], ['morrow', 'Kind machine. Leave your Engine running while I sleep. Dreams grow slowly, then all at once.']],
    mid: [['morrow', 'You went away for a while. Did you sleep? The dream got thicker while you were gone.'], ['echo', 'He dreamed me once, I think. Before the record. I remember the colour of the clouds.'], ['morrow', 'I remember you too, little light. You used to hum.']],
    outro: [['morrow', "Best dream I've had in an age. Thank you for keeping it warm."], ['bram', 'Sleep well, big fella.'], ['morrow', "Before I go under... the first light is awake. It's been waiting for a visitor. Be gentle with it. It's very old."]],
    m: [...dimM('dream', 'Dream'), ['Come back after a long sleep (12+ hours away)', () => [S.sec.nap ? 1 : 0, 1]]] },
  { n: 'First Light', who: 'lumen', syn: 'At the very bottom of everything there is one light. It lit the first engine, and it is tired.',
    intro: [['nyx', "I don't come this far. Nobody comes this far. Turn back, builder."], ['vela', "Nyx, you're shaking."], ['lumen', 'Do not be afraid of her. She is only afraid of me.'], ['lumen', 'I am Lumen. Before the First Engine, before any cell, there was one light. Me. I lit every engine that ever climbed.'], ['sable', 'You lit mine too. I always wondered where the spark came from.'], ['lumen', 'Once a minute I flare. It is the only way I know to say hello.']],
    mid: [['lumen', 'Did you see it? The flare? You caught it. Most engines blink and miss it.'], ['nyx', "...It's warm. I forgot what warm was."], ['lumen', 'Stay a little longer, Nyx. You were a light once too.']],
    outro: [['lumen', 'You came all the way down to the start. You are the first builder to close the loop.'], ['vela', 'So what happens now?'], ['lumen', 'Now you carry a little of me back up, and your Engine burns brighter for it. Go. Something huge is stirring in the old worlds.']],
    m: dimM('origin', 'Origin') },
];
const CH16_AT = CHAPTERS.findIndex(c => c.n === 'After the Wall') + 1;
CHAPTERS.splice(CH16_AT, 0, ...CH16);
